#include "degree_polarization_arithmetic.hpp"
struct HRReceipt {CFPoly denominator;int dimension=0,rank=0,generator_checks=0,stability_checks=0;std::vector<EBRow> basis;};
EBRow hr_flat(const CFPoly& a,const CFPoly& b,int m){EBRow out(size_t(2*m),Z(0));for(int i=0;i<m;++i){out[i]=a.at(i);out[m+i]=b.at(i);}return out;}
bool hr_contains(EBRow row,const EBEchelon& span){for(auto& [p,r]:span.rows){Z a=row[p];if(a!=Z(0))for(int j=p;j<span.width;++j)row[j]=row[j]-a*r[j];}return std::all_of(row.begin(),row.end(),[](const Z& c){return c==Z(0);});}
std::pair<CFPoly,CFPoly> hr_unflat(const EBRow& r,int m){require(int(r.size())==2*m,"rank cross-check vector width");return {CFPoly(std::vector<Z>(r.begin(),r.begin()+m)),CFPoly(std::vector<Z>(r.begin()+m,r.end()))};}
HRReceipt hr_check(std::vector<GCField> functions,const Json& old){functions.insert(functions.begin(),GCField(1));require(old.at("coordinate_hashes").arr.size()==functions.size(),"height coordinate hash count");CFPoly C{Z(1)};for(size_t i=0;i<functions.size();++i){require(hc_hash(functions[i])==old.at("coordinate_hashes").arr[i].scalar,"same canonical height coordinate");C=(C.exact(gc_gcd(C,functions[i].c))*functions[i].c).monic();}require(C==hc_read(old.at("common_denominator")),"same common height denominator");int m=C.degree();require(m==36||m==72,"fixed finite-algebra dimensions");CFPoly A,B;std::vector<CFPoly> aa,bb;for(size_t i=0;i<functions.size();++i){auto q=C.exact(functions[i].c);aa.push_back(functions[i].a*q);bb.push_back(functions[i].b*q);A=A+aa.back().scale(Z(long(i+1)));B=B+bb.back().scale(Z(long(i+1)));}A=A%C;B=B%C;EBEchelon span(2*m);CFPoly x{Z(0),Z(1)},power{Z(1)};for(int j=0;j<m;++j){span.insert(hr_flat((A*power)%C,(B*power)%C,m));span.insert(hr_flat((B*GCField::h*power)%C,(A*power)%C,m));power=(power*x)%C;}HRReceipt receipt;receipt.denominator=C;receipt.dimension=2*m;receipt.rank=int(span.rows.size());require(receipt.rank==old.at("polar_degree").integer(),"direct finite-algebra rank equals module-gcd height");for(size_t i=0;i<functions.size();++i){require(hr_contains(hr_flat(aa[i]%C,bb[i]%C,m),span)&&hr_contains(hr_flat((bb[i]*GCField::h)%C,aa[i]%C,m),span),"all numerator generators in actual multiplication image");receipt.generator_checks+=2;}
    for(auto& [pivot,row]:span.rows){(void)pivot;auto [a,b]=hr_unflat(row,m);require(hr_contains(hr_flat((a*x)%C,(b*x)%C,m),span)&&hr_contains(hr_flat((b*GCField::h)%C,a,m),span),"actual image stable under algebra generators");receipt.stability_checks+=2;receipt.basis.push_back(row);}bool rejected=false;for(int i=0;i<2*m&&!rejected;++i){EBRow e(size_t(2*m),Z(0));e[i]=Z(1);if(!hr_contains(e,span)){auto bad=receipt.basis[0];bad[i]=bad[i]+Z(1);require(!hr_contains(bad,span),"changed multiplication-image witness rejected");rejected=true;}}require(rejected,"proper-ideal corruption control executed");return receipt;}
void hr_emit(const HRReceipt& r){std::cout<<"{\"dimension\":"<<r.dimension<<",\"rank\":"<<r.rank<<",\"generator_membership_checks\":"<<r.generator_checks<<",\"ideal_stability_checks\":"<<r.stability_checks<<",\"changed_witness_rejected\":true,\"common_denominator\":";gc_emit_poly(std::cout,r.denominator);std::cout<<",\"echelon_basis\":[";for(size_t i=0;i<r.basis.size();++i){if(i)std::cout<<',';std::cout<<'[';for(size_t j=0;j<r.basis[i].size();++j)std::cout<<(j?",":"")<<'"'<<r.basis[i][j].x<<'"';std::cout<<']';}std::cout<<"]}";}
int main(int argc,char** argv){try{require(argc==4,"usage: height_rank kernel3-study global.json degree.json");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));GCField::h=rational(curve);auto global=read_json(argv[2]),old=read_json(argv[3]);std::vector<GCField> uc,vc;for(auto& c:global.at("U").arr)uc.push_back(hc_field(c));for(auto& c:global.at("V").arr)vc.push_back(hc_field(c));GCResidue::u=GCP(uc);auto xheight=hr_check({-uc[2],uc[1],-uc[0]},old.at("elementary_x_height"));require(xheight.rank==36,"elementary-x multiplication-image rank36");std::cerr<<"direct elementary-x algebra rank36 verified\n";GCResidue T(GCP{GCField(0),GCField(1)}),V{GCP(vc)};std::vector<GCResidue> sections;for(int i=0;i<=3;++i)for(int j=0;i+j<=3;++j){GCResidue s(1);for(int k=0;k<i;++k)s=s*T;for(int k=0;k<j;++k)s=s*V;sections.push_back(s);}std::vector<GCField> plucker;for(int i=0;i<10;++i)for(int j=i+1;j<10;++j)for(int k=j+1;k<10;++k){std::array<std::array<GCField,3>,3> m{};for(int row=0;row<3;++row){m[row][0]=sections[i].p.at(row);m[row][1]=sections[j].p.at(row);m[row][2]=sections[k].p.at(row);}plucker.push_back(hc_det(m));}require(plucker.size()==120,"all original Pluecker coordinates");auto pheight=hr_check(plucker,old.at("cubic_evaluation_height"));require(pheight.rank==72,"Pluecker multiplication-image rank72");std::cout<<"{\"scope\":\"P192-kernel3-independent-algorithm-height-crosscheck\",\"standing\":\"producer-unverified\",\"same_producer\":true,\"original_height_routine_called\":false,\"elementary_x\":";hr_emit(xheight);std::cout<<",\"cubic_Pluecker\":";hr_emit(pheight);std::cout<<"}\n";}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
